346	func installManagerForCurrentBinary() string {
347		execPath, err := executablePath()
348		if err != nil {
349			return installManagerUnknown
350		}
351	
352		realPath, err := filepath.EvalSymlinks(execPath)
353		if err != nil {
354			realPath = execPath
355		}
356		normalizedPath := strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/")
357	
358		switch {
359		case strings.Contains(normalizedPath, "/Cellar/") ||
360			strings.Contains(normalizedPath, "/opt/homebrew/") ||
361			strings.Contains(normalizedPath, "/linuxbrew/") ||
362			strings.Contains(normalizedPath, "/Caskroom/"):
363			return installManagerBrew
364		case strings.Contains(normalizedPath, "/mise/installs/"):
365			return installManagerMise
366		case strings.Contains(normalizedPath, "/scoop/apps/"):
367			return installManagerScoop
368		default:
369			return installManagerUnknown
370		}
371	}
